/**
 * CORE CHECK (cron-time-aware + upload-minute-aware):
 * - Uses cron_time from sync-jobs.json to know when each provider job runs
 * - GCS upload happens at 08:10 Rome time (server cron timezone)
 * - Evening jobs (cron_time >= 08:10, e.g. 21:30): ran YESTERDAY -> log in TODAY's GCS
 * - Early morning jobs (cron_time < 08:10, e.g. PVE at 02:00): ran TODAY -> log in TODAY's GCS
 * - Weekly jobs: check if the reference day (yesterday for evening, today for early-morning) is a cron_day
 * - Fail closed
 */

const gcsItems = $items("Get a list of objects");
const cfg = $json;

// Current time in Rome (CET/CEST) — server cron timezone
const nowRome      = $now.setZone('Europe/Rome');
const todayDOW     = nowRome.weekday % 7; // Luxon: 1=Mon..7=Sun -> %7: 0=Sun, 1=Mon, ..., 6=Sat
const yesterdayDOW = (todayDOW - 1 + 7) % 7;
const domToday     = nowRome.day;
const YM           = nowRome.toFormat('yyyy-MM');

// GCS log upload runs at this hour (Rome time)
const GCS_UPLOAD_MINUTE_OF_DAY = 8 * 60 + 10;
if (nowRome.hour * 60 + nowRome.minute <= GCS_UPLOAD_MINUTE_OF_DAY) throw new Error("Monitor scheduled before log upload cutoff");

// ---- Validate cfg ----
if (!cfg || typeof cfg !== "object") {
  throw new Error("sync-jobs.json missing or not an object");
}

// ---- Collect found objects (basenames only) ----
const foundFiles = new Set(
  gcsItems
    .map(i => i?.json?.name)
    .filter(Boolean)
    .map(name => String(name).split("/").pop())
);

// ---- Helper: normalize jobs array ----
function normalizeJobs(arr, providerName) {
  if (!Array.isArray(arr)) return [];
  return arr.map((j, idx) => {
    if (!j || typeof j !== "object") {
      throw new Error(`Invalid job entry in ${providerName}[${idx}]`);
    }
    const id        = String(j.id       ?? "").trim();
    const log_file = j.log_file ? String(j.log_file).trim() : j.log_file_prefix ? String(j.log_file_prefix).trim() : ''; 
    const required  = (j.required === undefined) ? true : j.required === true;
    const frequency = String(j.frequency ?? "daily").trim();
    const cron_days = Array.isArray(j.cron_days) ? j.cron_days : [];
    const cron_time = String(j.cron_time ?? "21:00").trim();

    if (!id)       throw new Error(`Missing job.id in ${providerName}[${idx}]`);
    if (!log_file) throw new Error(`Missing job.log_file/log_file_prefix in ${providerName}[${idx}]`);

    if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(cron_time)) throw new Error(`Invalid cron_time for ${id}`);
    if (!["daily","weekly","monthly"].includes(frequency)) throw new Error(`Unsupported frequency for ${id}`);
    return { provider: providerName, id, log_file, log_file_prefix: Boolean(j.log_file_prefix && !j.log_file), required, frequency, cron_days, cron_time };
  });
}

// ---- Support both schemas ----
const providerKeys = Object.keys(cfg).filter(k => k.endsWith("_jobs") && Array.isArray(cfg[k]));
let allJobs = [];
if (providerKeys.length > 0) {
  for (const k of providerKeys) {
    const providerName = k.replace(/_jobs$/, "");
    allJobs = allJobs.concat(normalizeJobs(cfg[k], providerName));
  }
} else if (Array.isArray(cfg.jobs)) {
  allJobs = normalizeJobs(cfg.jobs, "legacy");
} else {
  throw new Error("sync-jobs.json has no jobs array (expected jobs[] or *_jobs[])");
}

// ---- Filter: required jobs expected in TODAY's GCS folder ----
//
// Today's GCS prefix is expected to be populated by the 08:10 Europe/Rome upload:
//   - Evening job (cron_time >= 08:10, e.g. 21:30): ran YESTERDAY -> uploaded today 08:10 -> in GCS
//   - Early morning job (cron_time < 08:10, e.g. 02:00): ran TODAY -> uploaded today 08:10 -> in GCS
//   - Evening weekly job scheduled for TONIGHT: hasn't run yet -> NOT in today's GCS
//
// refDOW = the day-of-week on which the job ran to produce the log now in today's GCS.
//
const requiredJobs = allJobs.filter(j => {
  if (!j.required) return false;

  const [cronH, cronM = 0] = j.cron_time.split(":").map(Number);
  const cronMinuteOfDay = (cronH * 60) + cronM;
  const isEarlyMorning = cronMinuteOfDay < GCS_UPLOAD_MINUTE_OF_DAY;
  const refDOW = isEarlyMorning ? todayDOW : yesterdayDOW;
  if (j.log_file_prefix) { const refDate = isEarlyMorning ? nowRome : nowRome.minus({days:1}); j.log_file = `${j.log_file}-${refDate.toFormat("yyyy-MM")}.log`; }

  if (j.frequency === "weekly") {
    if (j.cron_days.length === 0) throw new Error(`Missing cron_days for weekly job ${j.id}`);
    return j.cron_days.map(Number).includes(refDOW);
  }

  if (j.frequency === "monthly") {
    // Monthly jobs run on day 1 by default; adapt manifest/script for other dates.
    // Early-morning (< 08:10): log in day 1's GCS -> check on days 1 and 2 (grace)
    // Evening (>= 08:10): log in day 2's GCS -> check on days 2 and 3 (grace)
    const startDOM = isEarlyMorning ? 1 : 2;
    return domToday === startDOM;
  }

  return true; // daily
});

// ---- Detect duplicates ----
const seen = new Map();
const duplicates = [];
for (const j of requiredJobs) {
  const prev = seen.get(j.log_file);
  if (prev) {
    duplicates.push({ log_file: j.log_file, a: prev, b: { provider: j.provider, id: j.id } });
  } else {
    seen.set(j.log_file, { provider: j.provider, id: j.id });
  }
}

if (duplicates.length > 0) {
  return [{
    json: {
      status: "CONFIG_ERROR_DUPLICATE_LOGS",
      ok: false,
      expected_jobs: requiredJobs.length,
      found_jobs: 0,
      missing_jobs: requiredJobs.length,
      present: [],
      missing: requiredJobs.map(j => ({ provider: j.provider, id: j.id, log_file: j.log_file })),
      missing_flat: requiredJobs.map(j => `[${j.provider}] ${j.log_file}`),
      config_errors: { duplicates }
    }
  }];
}

// ---- Check presence ----
const missing = [];
const present = [];
for (const job of requiredJobs) {
  if (foundFiles.has(job.log_file)) {
    present.push({ provider: job.provider, id: job.id, log_file: job.log_file });
  } else {
    missing.push({ provider: job.provider, id: job.id, log_file: job.log_file });
  }
}

const ok = missing.length === 0;

return [{
  json: {
    status: ok ? "OK" : "MISSING_LOGS",
    ok,
    expected_jobs: requiredJobs.length,
    found_jobs:    present.length,
    missing_jobs:  missing.length,
    present,
    missing,
    missing_flat: missing.map(m => `[${m.provider}] ${m.log_file}`),
    checkedDate: nowRome.toISODate(),
    host: $("Set_Context").first().json.host,
    bucket: $("Set_Context").first().json.bucket,
    prefix: $("Set_Prefix").first().json.prefix,
    providers: Array.from(new Set(requiredJobs.map(j => j.provider))).sort(),
    today_dow:     todayDOW,
    yesterday_dow: yesterdayDOW,
    today_dom:     domToday,
    gcs_upload_time: "08:10",
  }
}];

// Code: Parse Log — KV rclone/rsync + OneDrive format
// MODE: Run once for all items

const inputItems = $input.all();
const outputs    = [];

function findLast(lines, re) {
  for (let i = lines.length - 1; i >= 0; i--) {
    if (re.test(lines[i])) return lines[i];
  }
  return null;
}

function extractKV(line, key) {
  if (!line) return null;
  const m = line.match(new RegExp("\\b" + key + "=([^\\s]+)"));
  return m ? m[1] : null;
}

function toNumOrNull(v) {
  if (v === null || v === undefined) return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function uniqKeepLast(arr, max = 80) {
  const seen = new Set();
  const out  = [];
  for (let i = arr.length - 1; i >= 0; i--) {
    const s = arr[i];
    if (!seen.has(s)) {
      seen.add(s);
      out.push(s);
      if (out.length >= max) break;
    }
  }
  return out.reverse();
}

// ---- OneDrive log parser ----
// Format: [YYYY-MM-DD HH:MM:SS] MESSAGE
function parseOneDriveLog(lines, file) {
  const hasStart   = lines.some(l => /AVVIO OneDrive sync/i.test(l));
  const hasSuccess = lines.some(l => /SYNC COMPLETATO CON SUCCESSO/i.test(l));
  const hasQuota   = lines.some(l => /quota|no space|spazio esaurito/i.test(l));
  const hasAuth    = lines.some(l => /\bauth\b|unauthorized|401|token/i.test(l));

  let transferCount = null;
  const transferMatch = lines.map(l => l.match(/trasferiti[:\s]+(\d+)/i)).filter(Boolean);
  if (transferMatch.length > 0) {
    transferCount = parseInt(transferMatch[transferMatch.length - 1][1], 10);
  }

  const signals = [];
  if (!hasStart)   signals.push("MISSING_START");
  if (!hasSuccess) signals.push("MISSING_SUCCESS_MARKER");
  if (hasQuota)    signals.push("QUOTA_ERROR");
  if (hasAuth)     signals.push("AUTH_ERROR");

  const interestingRe = /(error|errore|failed|quota|spazio|unauthorized|token|warning)/i;
  const interestingLines = uniqKeepLast(
    [...lines.filter(l => interestingRe.test(l)), ...lines.slice(-3)],
    30
  );

  const ok = hasStart && hasSuccess && !hasQuota && !hasAuth;

  return {
    file,
    log_format: "onedrive",
    ok,
    rc:           ok ? 0 : 1,
    duration_s:   null,
    errors:       (hasQuota || hasAuth) ? 1 : 0,
    warnings:     0,
    sent_bytes:   null,
    recv_bytes:   null,
    total_size:   null,
    speedup:      null,
    transfer_count: transferCount,
    signals,
    interestingLines,
    debug: {
      textLen:    lines.join("\n").length,
      hasStart,
      hasSuccess,
      head:       lines.slice(0, 3).join("\n"),
    }
  };
}

for (let i = 0; i < inputItems.length; i++) {
  const it = inputItems[i];

  const rawName = it.json?.name || it.binary?.data?.fileName || "log.txt";
  let decodedName; try { decodedName = decodeURIComponent(String(rawName)); } catch { decodedName = String(rawName); }
  if (/(^|\/)incident-[^/]*\/|(^|\/)old\//i.test(decodedName)) {
    // Ignore archived incident/old log snapshots uploaded to GCS; monitor only current root logs.
    continue;
  }
  const file    = decodedName.split("/").pop();

  let text = "";
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, "data");
    text = buf.toString("utf8");
  } catch (e) {
    outputs.push({
      json: {
        file,
        ok:         false,
        rc:         null,
        duration_s: null,
        errors:     null,
        warnings:   null,
        sent_bytes: null,
        recv_bytes: null,
        total_size: null,
        speedup:    null,
        signals:    ["MISSING_BINARY_DATA"],
        interestingLines: [],
        debug: { error: String(e) },
      }
    });
    continue;
  }

  const lines = text.split(/\r?\n/).filter(l => l && l.trim().length > 0);

  // ---- Detect OneDrive log format ----
  const isKV =
  lines.some(l => /\bevent=START\b/.test(l)) ||
  lines.some(l => /\bevent=(RSYNC_END|RCLONE_END)\b/.test(l)) ||
  lines.some(l => /\bevent=SUMMARY\b/.test(l)) ||
  lines.some(l => /\bevent=END\b/.test(l));

  const isOneDrive =
    !isKV &&
    (
      lines.some(l => /AVVIO OneDrive sync|SYNC COMPLETATO/i.test(l))
    );

  if (isOneDrive) {
    outputs.push({ json: parseOneDriveLog(lines, file) });
    continue;
  }

  // ---- KV format (rclone, rsync, GCS) ----
  const startLine   = findLast(lines, /\bevent=START\b/);
  const toolEndLine = findLast(lines, /\bevent=(RSYNC_END|RCLONE_END)\b/);
  const summaryLine = findLast(lines, /\bevent=SUMMARY\b/);
  const endLine     = findLast(lines, /\bevent=END\b/);

  const hasEventStart = !!startLine;
  const hasToolEnd    = !!toolEndLine;
  const hasSummary    = !!summaryLine;
  const hasEventEnd   = !!endLine;

  const rcStr      = extractKV(endLine, "rc") || extractKV(summaryLine, "rc") || extractKV(toolEndLine, "rc");
  const rc         = toNumOrNull(rcStr);
  const duration_s = toNumOrNull(extractKV(endLine, "duration_s"));
  const errors     = toNumOrNull(extractKV(summaryLine, "errors"));
  const warnings   = toNumOrNull(extractKV(summaryLine, "warnings"));

  const result = {
    file,
    log_format: "kv",
    ok:         false,
    rc,
    duration_s,
    errors,
    warnings,
    sent_bytes:  extractKV(summaryLine, "sent_bytes")  || null,
    recv_bytes:  extractKV(summaryLine, "recv_bytes")  || null,
    total_size:  extractKV(summaryLine, "total_size")  || null,
    speedup:     extractKV(summaryLine, "speedup")     || null,
    signals:     [],
    interestingLines: [],
    debug: {
      textLen: text.length,
      head:    text.slice(0, 180),
      hasEventStart, hasEventEnd, hasSummary, hasToolEnd,
    }
  };

  if (!hasEventStart) result.signals.push("MISSING_START");
  if (!hasToolEnd)    result.signals.push("MISSING_TOOL_END");
  if (!hasSummary)    result.signals.push("MISSING_SUMMARY");
  if (!hasEventEnd)   result.signals.push("MISSING_END");
  if (hasEventStart && !hasEventEnd) result.signals.push("START_WITHOUT_END");
  if (rc !== null && rc !== 0)       result.signals.push("RC_NONZERO");
  if (errors   !== null && errors   > 0) result.signals.push("ERRORS_PRESENT");
  if (warnings  !== null && warnings > 0) result.signals.push("WARNINGS_PRESENT");

  // Strict contract: every marker, final rc and counts are mandatory.
  result.ok = hasEventStart && hasToolEnd && hasSummary && hasEventEnd &&
    rc === 0 && errors === 0 && warnings === 0;

  const interestingRe =
    /(warn|warning|error|failed|fatal|permission|denied|timeout|timed out|no space|read-only|broken pipe|connection reset|vanished|partial transfer|ssh:|host key|verification failed|auth|authentication|publickey|refused|unreachable|no route|network is unreachable)/i;

  const matched      = lines.filter(l => interestingRe.test(l));
  const summaryLines = lines.filter(l => /\bevent=SUMMARY\b/.test(l));
  const endLines     = lines.filter(l => /\bevent=END\b/.test(l)).slice(-3);

  result.interestingLines = uniqKeepLast([...summaryLines, ...matched, ...endLines], 80);

  outputs.push({ json: result });
}

return outputs;

// Prende il contenuto base64 dal nodo GitHub
const item = $json;

if (!item.content || item.encoding !== 'base64') {
  throw new Error('sync-jobs.json non valido o encoding non base64');
}

// Decodifica Base64 → stringa
const decoded = Buffer.from(item.content, 'base64').toString('utf-8');

// Parse JSON
let parsed;
try {
  parsed = JSON.parse(decoded);
} catch (e) {
  throw new Error('sync-jobs.json non è JSON valido');
}

// Ritorna il JSON pronto per n8n
return [{
  json: parsed
}];

// Convert each GCS log to UTF-8; one output per downloaded object.
const out=[];
for (let i=0;i<$input.all().length;i++) {
 const it=$input.all()[i]; const key=it.binary?.data?'data':Object.keys(it.binary||{})[0];
 if (!key) throw new Error(`Missing binary at item ${i}`);
 const buffer=await this.helpers.getBinaryDataBuffer(i,key);
 const text=buffer.toString('utf8').replace(/\u0000/g,'').replace(/\r\n/g,'\n');
 const name=String(it.json?.name||it.binary?.[key]?.fileName||`log-${i}.log`).split('/').pop();
 out.push({json:{log_file:name,log_text:text,log_bytes:buffer.length}});
}
return out;

// Code: Ticket? (definitivo)
// MODE: Run Once for All Items

const items = $input.all();

/**
 * Estrae e parse-a il JSON dalla risposta testuale del modello.
 * Supporta:
 * - JSON puro
 * - JSON dentro testo
 * - output in forma array (prende il primo oggetto se coerente)
 */
function parseModelJson(text) {
  if (typeof text !== 'string' || !text.trim()) {
    throw new Error('Risposta AI vuota o non testuale');
  }

  const tryParse = (s) => {
    const parsed = JSON.parse(s);
    if (Array.isArray(parsed)) {
      // Se il modello restituisce un array, assumiamo 1 elemento = 1 log
      // (se sono più elementi, vuol dire che il prompt/format è sbagliato a monte)
      if (parsed.length === 0) throw new Error('JSON array vuoto');
      if (typeof parsed[0] !== 'object' || parsed[0] === null) {
        throw new Error('JSON array non contiene oggetti');
      }
      return parsed[0];
    }
    return parsed;
  };

  // 1) parse diretto
  try {
    return tryParse(text);
  } catch (_) {
    // 2) fallback: estrai il primo blocco JSON {...}
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start === -1 || end === -1 || end <= start) {
      throw new Error('Nessun JSON trovato nella risposta AI');
    }
    const slice = text.slice(start, end + 1);
    return tryParse(slice);
  }
}

// Normalizza severità su una scala ordinabile
const SEV_RANK = {
  NONE: 0,
  INFO: 1,
  LOW: 2,
  MEDIUM: 3,
  HIGH: 4,
  CRITICAL: 5,
};

function normSeverity(sev) {
  const s = (sev ?? '').toString().trim().toUpperCase();
  if (!s) return 'UNKNOWN';
  if (SEV_RANK[s] !== undefined) return s;
  // accetta varianti comuni
  if (s === 'WARN' || s === 'WARNING') return 'LOW';
  if (s === 'SEVERE') return 'HIGH';
  return 'UNKNOWN';
}

function sevRank(sevNorm) {
  return SEV_RANK[sevNorm] ?? 2; // default prudente: LOW
}

function toNum(x) {
  const n = Number(x);
  return Number.isFinite(n) ? n : null;
}

function isNonEmptyString(s) {
  return typeof s === 'string' && s.trim().length > 0;
}

function buildFindingsText(findings) {
  return (findings || []).map((f, idx) => {
    const ev = (f.evidence_lines || []).filter(isNonEmptyString);
    const conf = toNum(f.confidence);
    const confTxt = conf === null ? 'n/a' : conf.toFixed(2);
    return [
      `#${idx + 1} [${f.category || 'UNKNOWN'}] conf=${confTxt}`,
      `Evidence:`,
      ...(ev.length ? ev.map(l => `- ${l}`) : ['- (none)']),
      `Action: ${f.recommended_action || '(none)'}`
    ].join('\n');
  }).join('\n\n');
}

/**
 * Policy di ticketing (generalista, non hardcoded su singoli errori):
 * - Se AI dice ai_ok=false => ticket
 * - Se severity >= MEDIUM => ticket
 * - Se severity è LOW/INFO ma ci sono findings "concreti" (evidence/action) con confidenza >= soglia => ticket
 *
 * Questo evita di perdere casi LOW ma reali (es. AUTH, permessi, config rischiose),
 * senza dover hardcodare stringhe specifiche.
 */
const POLICY = {
  // soglia di confidenza per ticketare anche a severità bassa
  lowSeverityConfidenceThreshold: 0.80,

  // severità minima che ticketiamo sempre
  alwaysTicketAtOrAbove: 'MEDIUM',

  // richiedi evidenza o azione per ticketare a severità bassa
  requireEvidenceOrActionForLowSeverity: true,
};

const out = [];

for (const it of items) {
  function pickAiText(j) {
    if (!j || typeof j !== 'object') return null;
    if (typeof j.output === 'string') return j.output;
    if (Array.isArray(j.output)) {
      for (const o of j.output) {
        if (typeof o?.content === 'string') return o.content;
        if (Array.isArray(o?.content)) {
          for (const c of o.content) {
            if (typeof c?.text === 'string') return c.text;
            if (typeof c?.content === 'string') return c.content;
          }
        }
        if (typeof o?.text === 'string') return o.text;
      }
    }
    if (Array.isArray(j.content)) {
      for (const c of j.content) {
        if (typeof c?.text === 'string') return c.text;
        if (typeof c?.content === 'string') return c.content;
      }
    }
    if (typeof j.content === 'string') return j.content;
    if (typeof j.text === 'string') return j.text;
    if (typeof j.response === 'string') return j.response;
    if (typeof j.message?.content === 'string') return j.message.content;
    if (typeof j.choices?.[0]?.message?.content === 'string') return j.choices[0].message.content;
    return null;
  }

  const aiText = pickAiText(it.json);
  const ai = parseModelJson(aiText);
  if (!ai.log_file && it.json?.log_file) ai.log_file = it.json.log_file;

  // Normalizza campi
  const sev = normSeverity(ai.severity);
  const rank = sevRank(sev);

  const findings = Array.isArray(ai.findings) ? ai.findings : [];
  const findingsCount = findings.length;

  // Calcola segnali “concreti”
  const hasConcreteFinding = findings.some(f => {
    const conf = toNum(f.confidence);
    const evCount = Array.isArray(f.evidence_lines) ? f.evidence_lines.filter(isNonEmptyString).length : 0;
    const hasAction = isNonEmptyString(f.recommended_action);
    const evidenceOrActionOk = (evCount > 0) || hasAction;

    if (POLICY.requireEvidenceOrActionForLowSeverity && !evidenceOrActionOk) return false;
    if (conf === null) return false; // senza confidenza non promuoviamo a ticket (puoi cambiare se vuoi)
    return conf >= POLICY.lowSeverityConfidenceThreshold;
  });

  const alwaysRank = sevRank(normSeverity(POLICY.alwaysTicketAtOrAbove));

  const aiOk = (ai.ai_ok === true) ? true : (ai.ai_ok === false ? false : null);

  // DECISIONE
  // Low-severity CONFIG notices on otherwise successful jobs (example: rclone SFTP
  // host-key-validation NOTICE) are useful in the email summary but too noisy for GLPI tickets.
  const lowSeverityConfigOnly =
    rank < alwaysRank &&
    findingsCount > 0 &&
    findings.every(f => (f.category || '').toString().trim().toUpperCase() === 'CONFIG');

  const should_ticket =
    (rank >= alwaysRank) ||
    (aiOk === false && !lowSeverityConfigOnly) ||
    (findingsCount > 0 && hasConcreteFinding && !lowSeverityConfigOnly);

  const findingsText = buildFindingsText(findings);

  out.push({
    json: {
      should_ticket,
      log_file: ai.log_file,
      severity: sev,
      ai_ok: aiOk,
      subject: `[Backup Sync] ${sev} - ${ai.log_file || 'UNKNOWN_LOG'}`,
      body:
`Log file: ${ai.log_file || 'UNKNOWN_LOG'}
Severity: ${sev}
AI_OK: ${aiOk}

Summary:
${ai.summary || '(none)'}

Findings:
${findingsText || '(none)'}
`,
      // debug/audit
      ai_raw: {
        ...ai,
        severity: sev,
      },
      ticket_policy_debug: {
        severity_rank: rank,
        always_ticket_at_or_above: POLICY.alwaysTicketAtOrAbove,
        low_sev_conf_threshold: POLICY.lowSeverityConfidenceThreshold,
        findings_count: findingsCount,
        has_concrete_finding: hasConcreteFinding,
      }
    }
  });
}

return out;

